static const struct mc_block_state *mc_block_state_lookup(const char *str, size_t len) {
    (void)len;
    size_t lo = 0;
    size_t hi = sizeof(mc_block_state_table)/sizeof(mc_block_state_table[0]);
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        int cmp = strcmp(str, mc_block_state_table[mid].name);
        if (cmp == 0) return &mc_block_state_table[mid];
        if (cmp < 0) hi = mid;
        else lo = mid + 1;
    }
    return NULL;
}

