int mc_block_state_id(const char *name, int fallback) {
    if (!name) return fallback;
    const struct mc_block_state *res = mc_block_state_lookup(name, strlen(name));
    return res ? res->id : fallback;
}

const char *mc_block_state_key(int id) {
    if (id < 0 || id > MC_BLOCK_STATE_MAX_ID) return NULL;
    return mc_block_state_by_id[id];
}
